private long closeOffsetOfFrame;

Engine(Main.Trace trace) {
    limConn = trace.connection;
    limStream = trace.stream;
    limBidi = trace.bidi;
    limUni = trace.uni;
    localBidi = trace.localBidi;
    localUni = trace.localUni;
    limCids = trace.cidLimit;
    localCids = trace.localCids.toArray(new byte[0][]);
    cidWidth = localCids.length == 0 ? 0 : localCids[0].length;
    seed[0] = trace.received[0];
    seed[1] = trace.received[1];
    seed[2] = trace.received[2];
    peerCid = trace.peerCid;
    peerToken = trace.peerToken;
    events = trace.events;
}

Map<String, Object> run() {
    for (int l = 0; l < 3; l++) {
        seen.add(new HashSet<>());
        ack[l] = new AckLog();
        crypto[l] = new ByteStore();
        largest[l] = seed[l];
        if (seed[l] >= 0) {
            seen.get(l).add(seed[l]);
        }
    }
    key[0] = true;
    key[1] = false;
    key[2] = false;
    peer.put(0L, new PeerCid(peerCid, peerToken));
    scal[S_THRESHOLD] = 0;
    scal[S_EPOCH] = 0;
    scal[S_ACTIVE] = 1;
    if (seed[2] >= 0) {
        epochs.put(0L, new long[] {seed[2], seed[2], 1});
    }
    for (int ev = 0; ev < events.size(); ev++) {
        Main.Event e = events.get(ev);
        if (e.keys != null) {
            if (!closed) {
                key[0] = key[1] = key[2] = false;
                for (String k : e.keys) {
                    if (k.equals("I")) {
                        key[0] = true;
                    } else if (k.equals("H")) {
                        key[1] = true;
                    } else {
                        key[2] = true;
                    }
                }
            }
            continue;
        }
        datagram(ev, e);
    }
    return output();
}

// ------------------------------------------------------------------ events

private void datagram(int ev, Main.Event e) {
    byte[] wire = e.wire;
    List<Long> auth = e.auth;
    dgBuffer = new ByteArrayOutputStream();
    dgAccepted = 0;
    dgPackets = 0;
    int pos = 0;
    int attempt = 0;
    while (pos < wire.length) {
        int start = pos;
        Env env = header(wire, start);
        if (env == null) {
            packetRows.add(Main.object("event", (long) ev, "packet", (long) attempt, "offset",
                    (long) start, "level", null, "pn", null, "epoch", null, "status", BAD_HEADER,
                    "sha256", null));
            dgPackets = attempt + 1;
            break;
        }
        dgPackets = attempt + 1;
        Long ann = (auth != null && attempt < auth.size()) ? auth.get(attempt) : null;
        packet(ev, attempt, start, env, ann);
        attempt++;
        pos = env.end;
        if (env.level == 2) {
            break;
        }
    }
    byte[] accepted = dgBuffer.toByteArray();
    datagramRows.add(Main.object("event", (long) ev, "packets", (long) dgPackets, "accepted",
            (long) dgAccepted, "bytes", (long) accepted.length, "sha256", sha256(accepted, 0, accepted.length)));
}

